import * as React from 'react'
import { ExternalLink, FileText, ChevronDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Popover, PopoverTrigger, PopoverContent } from '@/components/ui/popover'
import { productURL } from '@/components/ui/product-utils'
import { cn } from '@/lib/utils'
export interface CitationSource {
  id: string
  title: string
  url?: string
  description?: string
  quote?: string
  document?: string
  page?: number
}
export interface CitationsProps extends React.ComponentProps<'section'> {
  sources: CitationSource[]
  label?: string
  defaultExpanded?: boolean
  onSourceOpen?: (source: CitationSource) => void
}
interface CitationContext {
  sources: CitationSource[]
  onSourceOpen?: CitationsProps['onSourceOpen']
}
const Context = React.createContext<CitationContext | null>(null)
const useCitations = () => {
  const c = React.useContext(Context)
  if (!c) throw new Error('Citation parts need Citations.')
  return c
}
/** Source collections with inline references; URLs and quotes are supplied by the application. */
export function Citations({
  sources,
  label = 'Sources',
  defaultExpanded = true,
  onSourceOpen,
  children,
  className,
  ...props
}: CitationsProps) {
  const valid =
    sources.every((source) => source.id && source.title) &&
    new Set(sources.map((source) => source.id)).size === sources.length
  return (
    <Context.Provider value={{ sources, onSourceOpen }}>
      <section
        {...props}
        data-slot="citations"
        aria-label={label}
        className={cn('w-full min-w-0', className)}
      >
        {!valid ? (
          <p role="alert" className="text-sm text-destructive">
            Sources need unique IDs and titles.
          </p>
        ) : (
          (children ?? (
            <details open={defaultExpanded} className="rounded-xl border bg-background p-3">
              <summary className="flex cursor-pointer list-none items-center gap-2 text-sm font-medium">
                <FileText className="size-4 text-muted-foreground" />
                {sources.length} {label}
                <ChevronDown className="ms-auto size-4" />
              </summary>
              <CitationsList />
            </details>
          ))
        )}
      </section>
    </Context.Provider>
  )
}
/** One inline numeric reference with an accessible keyboard-triggered source preview. */
export function CitationReference({ sourceId, label }: { sourceId: string; label?: string }) {
  const c = useCitations(),
    index = c.sources.findIndex((source) => source.id === sourceId),
    source = c.sources[index]
  if (!source) return <span className="text-xs text-muted-foreground">[?]</span>
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          className="mx-0.5 h-5 min-w-5 px-1 align-baseline text-[10px]"
          aria-label={label ?? `Source ${index + 1}: ${source.title}`}
        >
          {index + 1}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        aria-label={`Source ${index + 1}: ${source.title}`}
        className="w-[min(22rem,calc(100vw-2rem))]"
      >
        <CitationCard source={source} />
      </PopoverContent>
    </Popover>
  )
}
/** Source list remains useful independently of inline markers. */
export function CitationsList() {
  const c = useCitations()
  return (
    <ol className="mt-3 space-y-2">
      {c.sources.map((source, index) => (
        <li key={source.id} className="flex items-start gap-2 rounded-lg border p-3">
          <span className="rounded bg-muted px-1.5 py-0.5 text-[10px]" dir="ltr">
            {index + 1}
          </span>
          <div className="min-w-0 flex-1">
            <CitationCard source={source} />
          </div>
        </li>
      ))}
    </ol>
  )
}
export function CitationCard({ source }: { source: CitationSource }) {
  const c = useCitations(),
    href = source.url && productURL(source.url)
  return (
    <div className="space-y-2 break-words text-xs">
      <p className="font-medium">{source.title}</p>
      {source.document && (
        <p className="text-muted-foreground">
          {source.document}
          {source.page ? ` · page ${source.page}` : ''}
        </p>
      )}
      {source.description && (
        <p className="leading-relaxed text-muted-foreground">{source.description}</p>
      )}
      {source.quote && (
        <blockquote className="border-s-2 ps-3 text-muted-foreground">{source.quote}</blockquote>
      )}
      {href && (
        <a
          href={href}
          target="_blank"
          rel="noopener noreferrer"
          onClick={() => c.onSourceOpen?.(source)}
          className="inline-flex items-center gap-1 text-primary underline underline-offset-4"
        >
          Open source
          <ExternalLink className="size-3" />
        </a>
      )}
    </div>
  )
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default:
          'h-[var(--ergon-control-height,2.25rem)] px-4 py-[var(--ergon-control-py,0.5rem)] has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

/**
 * Composes button variants, loading state, and optional slot rendering. Compact-density styles travel with the installed source.
 */
function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size }), className)}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import { usePortalContainer } from '@/components/ui/config-provider'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Popover as PopoverPrimitive } from 'radix-ui'

function Popover({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  align = 'center',
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal container={usePortalContainer()}>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          'z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95',
          className,
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  )
}

function PopoverAnchor({ ...props }: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...props} />
}

function PopoverHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="popover-header"
      className={cn('flex flex-col gap-1 text-sm', className)}
      {...props}
    />
  )
}

function PopoverTitle({ className, ...props }: React.ComponentProps<'h2'>) {
  return <div data-slot="popover-title" className={cn('font-medium', className)} {...props} />
}

function PopoverDescription({ className, ...props }: React.ComponentProps<'p'>) {
  return (
    <p
      data-slot="popover-description"
      className={cn('text-muted-foreground', className)}
      {...props}
    />
  )
}

export {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverAnchor,
  PopoverHeader,
  PopoverTitle,
  PopoverDescription,
}

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                '--ergon-control-height': density === 'compact' ? '30px' : '2.25rem',
                '--ergon-control-py': density === 'compact' ? '0.25rem' : '0.5rem',
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

import * as React from 'react'
import { useControllableState } from '@/components/ui/util'

/** Runs the latest cancellable action without publishing stale results after unmount. */
export function useAsyncAction() {
  const active = React.useRef<AbortController | null>(null)
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState('')
  React.useEffect(
    () => () => {
      active.current?.abort()
      active.current = null
    },
    [],
  )
  const cancel = React.useCallback(() => {
    active.current?.abort()
    active.current = null
    setBusy(false)
  }, [])
  const run = React.useCallback(async <T>(task: (signal: AbortSignal) => T | Promise<T>) => {
    active.current?.abort()
    const controller = new AbortController()
    active.current = controller
    setBusy(true)
    setError('')
    try {
      const value = await task(controller.signal)
      if (!controller.signal.aborted && active.current === controller) return value
    } catch (failure) {
      if (!controller.signal.aborted && active.current === controller)
        setError(failure instanceof Error ? failure.message : 'The action failed.')
    } finally {
      if (active.current === controller) {
        active.current = null
        setBusy(false)
      }
    }
    return undefined
  }, [])
  return { busy, error, run, cancel, clearError: () => setError('') }
}

/** Bounded immutable history for controlled or uncontrolled editors. */
export function useEditorHistory<T>({
  value,
  defaultValue,
  onChange,
  limit = 50,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
  limit?: number
}) {
  const [current, setCurrent] = useControllableState({ value, defaultValue, onChange })
  const [past, setPast] = React.useState<T[]>([])
  const [future, setFuture] = React.useState<T[]>([])
  const expected = React.useRef(current)
  React.useEffect(() => {
    if (value !== undefined && value !== expected.current) {
      expected.current = value
      setPast([])
      setFuture([])
    }
  }, [value])
  const apply = (next: T) => {
    expected.current = next
    setCurrent(next)
  }
  return {
    value: current,
    canUndo: past.length > 0,
    canRedo: future.length > 0,
    commit(next: T) {
      if (Object.is(next, current)) return
      setPast((previous) => [...previous, current].slice(-Math.max(1, Math.min(100, limit))))
      setFuture([])
      apply(next)
    },
    undo() {
      if (!past.length) return
      setPast(past.slice(0, -1))
      setFuture([current, ...future])
      apply(past[past.length - 1])
    },
    redo() {
      if (!future.length) return
      setPast([...past, current])
      setFuture(future.slice(1))
      apply(future[0])
    },
  }
}

/** Accepts explicit web/blob/image URLs and relative paths, never executable protocols. */
export function productURL(value: string, image = false): string | undefined {
  const clean = value.trim()
  if (
    !clean ||
    [...clean].some((character) => character.charCodeAt(0) <= 32 || character.charCodeAt(0) === 127)
  )
    return
  if (image && /^data:image\/(?:png|jpeg|webp|gif);base64,[\da-z+/=]+$/i.test(clean)) return clean
  try {
    const url = new URL(clean, 'https://ergon.invalid/')
    if (['http:', 'https:'].includes(url.protocol) || (image && url.protocol === 'blob:'))
      return clean
  } catch {
    /* Invalid input remains inert. */
  }
}
export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
/** Creates client-side entity IDs in secure and plain-HTTP browser contexts. */
export const productId = () => {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  const bytes = globalThis.crypto.getRandomValues(new Uint8Array(16))
  bytes[6] = (bytes[6] & 15) | 64
  bytes[8] = (bytes[8] & 63) | 128
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

import * as React from 'react'
import { breakpoints, type Breakpoint } from '@/lib/responsive'
export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value === undefined ? internal : value
  const currentRef = React.useRef(current),
    valueRef = React.useRef(value),
    changeRef = React.useRef(onChange)
  currentRef.current = current
  valueRef.current = value
  changeRef.current = onChange
  const set = React.useCallback((next: T | ((previous: T) => T)) => {
    const previous = currentRef.current
    const result = typeof next === 'function' ? (next as (previous: T) => T)(previous) : next
    if (Object.is(previous, result)) return
    currentRef.current = result
    if (valueRef.current === undefined) setInternal(result)
    changeRef.current?.(result)
  }, [])
  return [current, set] as const
}
export function useMediaQuery(query: string) {
  const [matches, setMatches] = React.useState(
    () => typeof window !== 'undefined' && window.matchMedia(query).matches,
  )
  React.useEffect(() => {
    const m = window.matchMedia(query)
    const update = () => setMatches(m.matches)
    update()
    m.addEventListener('change', update)
    return () => m.removeEventListener('change', update)
  }, [query])
  return matches
}
export function useDebouncedValue<T>(value: T, delay = 250) {
  const [debounced, set] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => set(value), delay)
    return () => clearTimeout(id)
  }, [value, delay])
  return debounced
}
export async function copyToClipboard(text: string) {
  await navigator.clipboard.writeText(text)
}
export function useBreakpoints() {
  const [width, setWidth] = React.useState(() =>
    typeof window === 'undefined' ? 0 : window.innerWidth,
  )
  React.useEffect(() => {
    const update = () => setWidth(window.innerWidth)
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])
  return Object.fromEntries(
    Object.entries(breakpoints).map(([key, min]) => [key, width >= min]),
  ) as Record<Breakpoint, boolean>
}

import type { CSSProperties } from 'react'
export const breakpoints = { xs: 0, sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536 } as const
export type Breakpoint = keyof typeof breakpoints
export type Responsive<T> = T | Partial<Record<Breakpoint, T>>
export function responsiveStyle<T>(value: Responsive<T> | undefined, name: string): CSSProperties {
  if (value === undefined) return {}
  const values = typeof value === 'object' && value !== null ? value : { xs: value }
  return Object.fromEntries(
    Object.entries(values).map(([key, v]) => [`--${name}-${key}`, v]),
  ) as CSSProperties
}
export const responsiveCSS = Object.entries(breakpoints)
  .map(([, min], index) => {
    const fallback = (name: string, initial: string) =>
      Object.keys(breakpoints)
        .slice(0, index + 1)
        .reduce((result, key) => `var(--${name}-${key},${result})`, initial)
    return `@media(min-width:${min}px){.ergon-col{width:calc(${fallback('span', '24')} / 24 * 100%);margin-inline-start:calc(${fallback('offset', '0')} / 24 * 100%);order:${fallback('order', '0')}}.ergon-flex{gap:${fallback('gap', '12px')};flex-direction:${fallback('direction', 'row')}}}`
  })
  .join('')
